\set ON_ERROR_STOP 1
begin;
reset role;
create temp table correction (id uuid, before_row jsonb, payments jsonb);
grant all on correction to authenticated;
select test.login('tm_a');
insert into correction(id) select create_lead('{"name":"Profile Test","company":"Profile Test Co","email":"profile.edit@example.com","phone":"9847650123","leadSource":"Walk-in"}', array['AI_CALLING']);
select send_lead_to_accounts((select id from correction), 120000, null);
select test.must_fail($$select accounts_customer_details((select id from correction),null)$$, 'Sales cannot use Accounts correction', 'FORBIDDEN');
reset role;
update correction set before_row = (select to_jsonb(c) from customers c where c.id=correction.id), payments = (select coalesce(jsonb_agg(to_jsonb(p)), '[]') from customer_payments p where p.customer_id=correction.id);
select test.login('acc_m');
select test.check(accounts_customer_details((select id from correction),null)->>'company'='Profile Test Co','prefills current record');
select accounts_customer_details((select id from correction),'{"name":"Correct Contact","company":"Correct Business","phone":"9847650321","whatsapp":"9847650322","email":"profile.correct@example.com","city":"Pune","address":"Pune, Maharashtra","businessCategory":"Retail"}');
select test.check(accounts_customer_details((select id from correction),null)->>'city'='Pune','saved profile persists on reopening');
select test.must_fail($$select accounts_customer_details((select id from correction),'{"dealAmount":1}')$$,'financial fields refused','Only customer profile');
select test.must_fail($$select accounts_customer_details((select id from correction),'{"name":"X","company":"Y","phone":"bad"}')$$,'invalid phone refused','valid mobile');
select test.must_fail($$select accounts_customer_details(gen_random_uuid(),null)$$,'unpermitted customer refused','NOT_FOUND');
reset role;
select test.check((select (to_jsonb(c)-array['name','company','phone','whatsapp','email','city','address','business_category','updated_at','updated_by','search_text']) = (x.before_row-array['name','company','phone','whatsapp','email','city','address','business_category','updated_at','updated_by','search_text']) from customers c join correction x on x.id=c.id),'customer identity, attribution and financial fields unchanged');
select test.check((select payments = (select coalesce(jsonb_agg(to_jsonb(p)), '[]') from customer_payments p where p.customer_id=x.id) from correction x),'payment history unchanged');
select test.check(exists(select 1 from audit_logs where entity_id=(select id from correction) and action='CUSTOMER_UPDATED' and metadata #>> '{changes,name,from}'='Profile Test' and metadata #>> '{changes,name,to}'='Correct Contact' and actor_id is not null and created_at is not null),'audit contains editor, time and before/after values');
insert into auth.users(email) values ('profile.linked@example.com');
insert into customer_client_accounts(customer_id,auth_user_id,email) select x.id,u.id,'profile.linked@example.com' from correction x cross join auth.users u where u.email='profile.linked@example.com';
select test.login('acc_m');
select test.must_fail($$select accounts_customer_details((select id from correction), (accounts_customer_details((select id from correction),null)-'hasClientLogin') || '{"email":"profile.replaced@example.com"}'::jsonb)$$,'linked login email cannot be changed through profile editor','already has a login');
reset role;
select test.check((select email='profile.correct@example.com' from customers where id=(select id from correction)),'refused login email correction leaves customer unchanged');
rollback;
